package Tv2.Controller;
import Tv2.View.XepLopPage;import MainPage.Controller.PageTasks;import MainPage.View.Workspace;import Model.*;import Service.*;import java.awt.Component;import java.time.*;import java.util.*;import java.math.BigDecimal;
public class XepLopController {
 public static void open(Component owner,int b,int hv,Runnable done){open(owner,b,hv,null,done);}
 public static void open(Component owner,int b,int hv,Integer registration,Runnable done){XepLopPage v=new XepLopPage();v.title("XẾP LỚP — Học viên #"+hv,"Chọn lớp phù hợp khóa học; kiểm tra sĩ số trước khi xác nhận");v.columns("Mã lớp","Tên lớp","Khóa #","Sĩ số","Học phí","Bắt đầu");v.onSelection(()->{int row=v.selected();v.setSelectionText(row<0?"Chưa chọn lớp":"Đã chọn: "+v.value(row,1));});var confirm=v.action("Xác nhận xếp lớp",()->{int r=v.selected();if(r<0)return;int id=(int)v.value(r,0);PageTasks.actor(v,b,actor->PageTasks.run(v,()->assign(b,hv,id,actor,registration),ok->{done.run();javax.swing.SwingUtilities.getWindowAncestor(v).dispose();}));});confirm.setEnabled(false);Workspace.window(owner,"Xếp lớp",v);PageTasks.run(v,()->{var regs=new DangKyHocService().selectAll(b);var pending=regs.stream().filter(x->x.getMaHocVien()==hv&&"CHO_XEP_LOP".equals(x.getTrangThai())&&(registration==null||x.getMaDangKy()==registration)).toList();PageTasks.require(registration==null||!pending.isEmpty(),"Đăng ký không còn chờ xếp lớp");var list=new LopHocService().selectAll(b);return list.stream().filter(l->"DANG_MO".equals(l.getTrangThai())&&(pending.isEmpty()||pending.stream().anyMatch(p->Objects.equals(p.getMaKhoaHoc(),l.getMaKhoaHoc())))).map(l->new Object[]{l.getMaLop(),l.getTenLop(),l.getMaKhoaHoc(),regs.stream().filter(x->Objects.equals(x.getMaLop(),l.getMaLop())&&"DANG_HOC".equals(x.getTrangThai())).count()+" / "+PageTasks.text(l.getSiSoToiDa()),l.getHocPhiMacDinh(),l.getNgayBatDau()}).toArray(Object[][]::new);},rows->{v.rows(rows);confirm.setEnabled(rows.length>0);v.status("Lớp phù hợp: "+rows.length);});}
 private static boolean assign(int b,int hv,int id,int actor,Integer registration){var hs=new HocVienService();var h=hs.getByMaHocVien(b,hv);PageTasks.require(h!=null&&Set.of("CHINH_THUC","CHO_XEP_LOP").contains(h.getTrangThai()),"Chỉ xếp lớp cho hồ sơ đã xác nhận");var l=new LopHocService().getByMaLop(b,id);PageTasks.require(l!=null&&"DANG_MO".equals(l.getTrangThai()),"Lớp không hoạt động");var ds=new DangKyHocService();var all=ds.reload(b);PageTasks.require(all.stream().noneMatch(x->x.getMaHocVien()==hv&&Objects.equals(x.getMaKhoaHoc(),l.getMaKhoaHoc())&&Set.of("DANG_HOC","TAM_NGHI").contains(x.getTrangThai())),"Đã có đăng ký đang học cùng khóa; cần nghiệp vụ chuyển lớp");long size=all.stream().filter(x->Objects.equals(x.getMaLop(),id)&&"DANG_HOC".equals(x.getTrangThai())).map(DangKyHocModel::getMaHocVien).distinct().count();PageTasks.require(l.getSiSoToiDa()==null||size<l.getSiSoToiDa(),"Lớp đã đủ sĩ số");var pending=all.stream().filter(x->x.getMaHocVien()==hv&&Objects.equals(x.getMaKhoaHoc(),l.getMaKhoaHoc())&&"CHO_XEP_LOP".equals(x.getTrangThai())&&(registration==null||x.getMaDangKy()==registration)).toList();PageTasks.require(registration==null||pending.size()==1,"Đăng ký đã thay đổi; tải lại hồ sơ");PageTasks.require(pending.size()<=1,"Có nhiều đăng ký chờ cùng khóa; cần xử lý thủ công");var d=pending.isEmpty()?new DangKyHocModel():pending.get(0);if(pending.isEmpty()){d.setMaHocVien(hv);d.setMaKhoaHoc(l.getMaKhoaHoc());d.setNgayDangKy(LocalDate.now());d.setMaNguoiDangKy(actor);d.setHocPhiThoaThuan(l.getHocPhiMacDinh());if(l.getMaKhoaHoc()!=null){var c=new DanhMucService().getByMaDanhMuc(b,l.getMaKhoaHoc());PageTasks.require(c!=null,"Không tìm thấy khóa học");d.setTongSoBuoi(PageTasks.number(c.getCauHinh(),"TongSoBuoi"));PageTasks.require(d.getTongSoBuoi()!=null&&d.getTongSoBuoi()>0,"Khóa chưa có số buổi");}}LocalDate start=LocalDate.now();if(l.getNgayBatDau()!=null&&l.getNgayBatDau().isAfter(start))start=l.getNgayBatDau();PageTasks.require(l.getNgayKetThuc()==null||!start.isAfter(l.getNgayKetThuc()),"Lớp đã kết thúc");d.setMaLop(id);d.setNgayBatDau(start);d.setTrangThai("DANG_HOC");if(d.getTongSoBuoi()!=null){var tk=new ThoiKhoaBieuService().getByMaLop(b,id);int n=0;LocalDate finish=null;for(LocalDate day=start;!day.isAfter(start.plusYears(3))&&(l.getNgayKetThuc()==null||!day.isAfter(l.getNgayKetThuc()));day=day.plusDays(1)){for(var t:tk)if(t.isTrangThai()&&t.getThuTrongTuan()==day.getDayOfWeek().getValue()&&!day.isBefore(t.getTuNgay())&&(t.getDenNgay()==null||!day.isAfter(t.getDenNgay())))n++;if(n>=d.getTongSoBuoi()){finish=day;break;}}d.setNgayKetThucDuKien(finish);}PageTasks.require(pending.isEmpty()?ds.insert(b,d):ds.update(b,d),"Không ghi được đăng ký");if(!"CHINH_THUC".equals(h.getTrangThai())){String prev=h.getTrangThai();h.setTrangThai("CHINH_THUC");h.setNgayChinhThuc(LocalDate.now());PageTasks.require(hs.update(b,h),"Đã xếp lớp nhưng chưa đổi trạng thái hồ sơ");HocThuController.log(b,hv,actor,prev,"CHINH_THUC",l.getMaKhoaHoc());}return true;}
}
